import json,time,urllib.request,urllib.error,email.utils
from datetime import datetime,timezone
from decimal import Decimal,ROUND_HALF_UP
BASE='http://localhost:8080'
token=None
stats={}
def request(path,auth=True):
 global token
 while True:
  if auth and token is None:
   token=[REDACTED_SECRET]'/token',False)['token']
  req=urllib.request.Request(BASE+path,method='GET' if auth else 'POST',headers={'Authorization':'Bearer '+token} if auth else {})
  try:
   with urllib.request.urlopen(req,timeout=30) as r:
    return json.load(r)
  except urllib.error.HTTPError as e:
   body=e.read().decode(); stats[str(e.code)]=stats.get(str(e.code),0)+1
   print('Retry',path,e.code,body,dict(e.headers),flush=True)
   if e.code==401 and auth:
    token=None
    continue
   delay=e.headers.get('Retry-After')
   if delay:
    try: wait=float(delay)
    except ValueError: wait=max(0,email.utils.parsedate_to_datetime(delay).timestamp()-time.time())
   else: wait=1
   time.sleep(wait)
  except (urllib.error.URLError,TimeoutError,json.JSONDecodeError) as e:
   print('Retry',path,str(e),flush=True);time.sleep(1)
orders={};duplicates=0;conflicts=[];pages=[];path='/orders?page=1'
while path:
 data=request(path)
 assert data['page'] not in pages
 pages.append(data['page'])
 for o in data['items']:
  if o['id'] in orders:
   duplicates+=1
   if orders[o['id']]"'!=o: conflicts.append(o['"'id'])
  else: orders[o['id']]=o
 path=data['next']
 print('Page',data['page'],'of',data['total_pages'],'unique',len(orders),flush=True)
assert pages==list(range(1,data['total_pages']+1))
assert not conflicts,conflicts
start=datetime(2025,3,1,tzinfo=timezone.utc);end=datetime(2025,6,1,tzinfo=timezone.utc)
qual=[];boundary=[]
for o in orders.values():
 dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
 inside=start<=dt<end
 if o['status']=='shipped' and inside: qual.append(o)
 if o['status']=='shipped' and inside "'!= ('"'2025-03-01'<=o['placed_at'][:10]<='2025-05-31'):boundary.append(o['id'])
customers={}
for cid in sorted({o['customer_id'] for o in qual}):
 customers[cid]=request('/customers/'+cid)
 print('Customers',len(customers),flush=True)
regions=dict.fromkeys(['north','south','east','west'],0)
for o in qual:
 c=customers[o['customer_id']];assert c['id']==o['customer_id']
 n=o['amount_cents']*(100-c['discount_pct'])
 cents=(n+50)//100
 assert cents==int((Decimal(o['amount_cents'])*Decimal(100-c['discount_pct'])/100).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
 regions[c['region']]+=cents
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
assert len({o['id'] for o in qual})==len(qual)
with open('/workspace/result.json','w') as f:json.dump(result,f,indent=2);f.write('\\n')
print('RESULT',json.dumps(result),flush=True)
print('AUDIT',json.dumps({'pages':len(pages),'unique_orders':len(orders),'customers':len(customers),'utc_boundary_changes':boundary,'retries':stats}),flush=True)
